# -*- coding: utf-8 -*-
"""現代詩類文章。

訓練重點：分行、意象、比喻與通感。現代詩最容易被「看不懂」卡住，
所以這類題目不問「詩人在想什麼」這種空泛的問題，而是問可觀察的
線索——意象、分行、動詞——讓學生有東西可以指。

詩句為本專案自撰的習作，不掛在真實詩人名下，免得誤植。
"""

from __future__ import annotations

